package si.contacts.store;

import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import si.contacts.workspace.Membership;

/** Membership facts needed before a WorkspaceScope exists. Used only by WorkspaceAccess. */
@Repository
public class AccessStore {
  private final JdbcClient db;

  public AccessStore(JdbcClient db) {
    this.db = db;
  }


  public Optional<String> roleOf(UUID workspaceId, UUID userId) {
    return db.sql("SELECT role FROM memberships WHERE workspace_id = ? AND user_id = ?")
        .params(workspaceId, userId)
        .query(String.class)
        .optional();
  }

  public void lockWorkspace(UUID workspaceId) {
    db.sql("SELECT id FROM workspaces WHERE id = ? FOR UPDATE").param(workspaceId).query(UUID.class).optional();
  }

  public UUID createWorkspace(String name, UUID ownerId) {
    UUID id = UUID.randomUUID();
    db.sql("INSERT INTO workspaces (id, name) VALUES (?, ?)").params(id, name).update();
    db.sql("INSERT INTO memberships (workspace_id, user_id, role) VALUES (?, ?, 'OWNER')").params(id, ownerId).update();
    return id;
  }

  public List<Membership> workspacesOf(UUID userId) {
    return db.sql(
            "SELECT w.id, w.name, m.role FROM memberships m JOIN workspaces w ON w.id = m.workspace_id"
                + " WHERE m.user_id = ? ORDER BY lower(w.name), w.id")
        .param(userId)
        .query((rs, i) -> new Membership(rs.getObject(1, UUID.class), rs.getString(2), rs.getString(3)))
        .list();
  }

  /** Turns pending invitations for the verified email into memberships, then removes them. */
  public void activateInvitations(UUID userId, String emailLower) {
    db.sql(
            "WITH taken AS (DELETE FROM invitations WHERE email_lower = ? RETURNING workspace_id, role)"
                + " INSERT INTO memberships (workspace_id, user_id, role)"
                + " SELECT workspace_id, ?, role FROM taken ON CONFLICT DO NOTHING")
        .params(emailLower, userId)
        .update();
  }
}
package si.contacts.store;

import java.time.OffsetDateTime;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import si.contacts.workspace.WorkspaceScope;

/** Members and invitations of one Workspace. */
@Repository
public class MemberStore {
  private final JdbcClient db;

  public MemberStore(JdbcClient db) {
    this.db = db;
  }

  public record MemberRow(UUID userId, String email, String displayName, String role) {}

  public record InvitationRow(UUID id, String email, String role, OffsetDateTime createdAt) {}

  public List<MemberRow> members(WorkspaceScope s) {
    return db.sql(
            "SELECT u.id, u.email, u.display_name, m.role FROM memberships m JOIN users u ON u.id = m.user_id"
                + " WHERE m.workspace_id = ? ORDER BY lower(coalesce(u.display_name, u.email)), u.id")
        .param(s.workspaceId())
        .query((rs, i) -> new MemberRow(rs.getObject(1, UUID.class), rs.getString(2), rs.getString(3), rs.getString(4)))
        .list();
  }

  public Optional<MemberRow> member(WorkspaceScope s, UUID userId) {
    return members(s).stream().filter(m -> m.userId().equals(userId)).findFirst();
  }

  public List<InvitationRow> invitations(WorkspaceScope s) {
    return db.sql("SELECT id, email, role, created_at FROM invitations WHERE workspace_id = ? ORDER BY created_at, id")
        .param(s.workspaceId())
        .query(
            (rs, i) ->
                new InvitationRow(
                    rs.getObject(1, UUID.class), rs.getString(2), rs.getString(3), rs.getObject(4, OffsetDateTime.class)))
        .list();
  }

  /** Whether a Member with this email (ignoring case) or an invitation for it exists. */
  public boolean memberOrInvited(WorkspaceScope s, String emailLower) {
    return db.sql(
            "SELECT EXISTS (SELECT 1 FROM memberships m JOIN users u ON u.id = m.user_id"
                + " WHERE m.workspace_id = ? AND u.email_lower = ?)"
                + " OR EXISTS (SELECT 1 FROM invitations WHERE workspace_id = ? AND email_lower = ?)")
        .params(s.workspaceId(), emailLower, s.workspaceId(), emailLower)
        .query(Boolean.class)
        .single();
  }

  public boolean isMember(WorkspaceScope s, UUID userId) {
    return db.sql("SELECT EXISTS (SELECT 1 FROM memberships WHERE workspace_id = ? AND user_id = ?)")
        .params(s.workspaceId(), userId)
        .query(Boolean.class)
        .single();
  }

  public void addMember(WorkspaceScope s, UUID userId, String role) {
    db.sql("INSERT INTO memberships (workspace_id, user_id, role) VALUES (?, ?, ?)").params(s.workspaceId(), userId, role).update();
  }

  public InvitationRow invite(WorkspaceScope s, String email, String role) {
    UUID id = UUID.randomUUID();
    return db.sql(
            "INSERT INTO invitations (id, workspace_id, email, email_lower, role) VALUES (?, ?, ?, lower(?), ?)"
                + " RETURNING id, email, role, created_at")
        .params(id, s.workspaceId(), email, email, role)
        .query(
            (rs, i) ->
                new InvitationRow(
                    rs.getObject(1, UUID.class), rs.getString(2), rs.getString(3), rs.getObject(4, OffsetDateTime.class)))
        .single();
  }

  public int owners(WorkspaceScope s) {
    return db.sql("SELECT count(*) FROM memberships WHERE workspace_id = ? AND role = 'OWNER'")
        .param(s.workspaceId())
        .query(Integer.class)
        .single();
  }

  public void changeRole(WorkspaceScope s, UUID userId, String role) {
    db.sql("UPDATE memberships SET role = ? WHERE workspace_id = ? AND user_id = ?").params(role, s.workspaceId(), userId).update();
  }

  public void remove(WorkspaceScope s, UUID userId) {
    db.sql("DELETE FROM memberships WHERE workspace_id = ? AND user_id = ?").params(s.workspaceId(), userId).update();
  }

  public boolean cancelInvitation(WorkspaceScope s, UUID id) {
    return db.sql("DELETE FROM invitations WHERE workspace_id = ? AND id = ?").params(s.workspaceId(), id).update() > 0;
  }
}
package si.contacts.store;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Locale;
import java.util.Optional;
import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import si.contacts.user.User;

/** Users are not Workspace-owned; they are known by their sign-in identity. */
@Repository
public class UserStore {
  private final JdbcClient db;

  public UserStore(JdbcClient db) {
    this.db = db;
  }

  public User upsert(String uid, String email, boolean verified, String name) {
    return db.sql(
            "INSERT INTO users (id, firebase_uid, email, email_lower, email_verified, display_name)"
                + " VALUES (?, ?, ?, ?, ?, ?)"
                + " ON CONFLICT (firebase_uid) DO UPDATE SET email = EXCLUDED.email,"
                + " email_lower = EXCLUDED.email_lower, email_verified = EXCLUDED.email_verified,"
                + " display_name = EXCLUDED.display_name"
                + " RETURNING id, firebase_uid, email, email_verified, display_name")
        .params(UUID.randomUUID(), uid, email, email == null ? null : email.toLowerCase(Locale.ROOT), verified, name)
        .query(UserStore::map)
        .single();
  }

  public Optional<User> findVerifiedByEmail(String emailLower) {
    return db.sql(
            "SELECT id, firebase_uid, email, email_verified, display_name FROM users"
                + " WHERE email_lower = ? AND email_verified ORDER BY created_at LIMIT 1")
        .param(emailLower)
        .query(UserStore::map)
        .optional();
  }

  static User map(ResultSet rs, int i) throws SQLException {
    return new User(
        rs.getObject("id", UUID.class),
        rs.getString("firebase_uid"),
        rs.getString("email"),
        rs.getBoolean("email_verified"),
        rs.getString("display_name"));
  }
}
